#!/bin/bash
cd ~/c12_bench2; export OMP_NUM_THREADS=1 MKL_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1 PYTHONPATH=challenge2:hackathon:challenge1 C12_DL_CKPT=$HOME/c12_bench2/ckpt/unet_lofo_u32_all.pt C12_DL_THR=0.5; while pgrep -u $USER -f "m evaluation.run" >/dev/null; do sleep 30; done; R() { n=$1; shift; ~/c12/.venv/bin/python -m evaluation.run "$@" --workers 15 --out results/$n.jsonl > results/$n.log 2>&1; }; for b in "250000 75" "500000 150" "2000000 600"; do set -- $b; R curve_ucb_$1 --methods bo_roi_auto_ucb_dlf --split dev --n 100 --budget $1 --meas-cap $2; R curve_coarse_$1 --methods bo_coarse_ucb_dlf --split dev --n 100 --budget $1 --meas-cap $2; done
